using System.Windows;
using System.Windows.Controls;
using ReviveOS.WindowsOptimizer;
namespace ReviveOS.UI;
public sealed class DeepDialog:Window {
 readonly StackPanel choices=new();readonly TextBox log=new(){IsReadOnly=true,TextWrapping=TextWrapping.Wrap,Height=150,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(8)};
 readonly List<(CheckBox Box,DeepAction Action)> items=[];bool busy;
 public DeepDialog(DeepOptimizer optimizer){async Task RestoreAll(){if(!ReviveOS.Security.AdminBroker.IsAdministrator()&&optimizer.HasAdministrativePending)await ReviveOS.Security.AdminBroker.Run("deep-restore");else await optimizer.Restore();}
 Title="Otimização profunda — ajustes reais com rollback";Width=800;Height=680;var dock=new DockPanel{Margin=new Thickness(12)};var buttons=new WrapPanel();var plan=new Button{Content="Analisar e preparar plano",Margin=new Thickness(4),Padding=new Thickness(8)};var apply=new Button{Content="Aplicar selecionados",Margin=new Thickness(4),Padding=new Thickness(8)};var undo=new Button{Content="Restaurar ajustes profundos",Margin=new Thickness(4),Padding=new Thickness(8)};buttons.Children.Add(plan);buttons.Children.Add(apply);buttons.Children.Add(undo);var single=new Button{Content="Restaurar selecionados",Margin=new Thickness(4),Padding=new Thickness(8)};buttons.Children.Add(single);single.Click+=async(_,_)=>{if(busy)return;busy=true;try{var errors=new List<Exception>();foreach(var item in items.Where(x=>x.Box.IsChecked==true)){try{if(item.Action.RequiresAdmin&&!ReviveOS.Security.AdminBroker.IsAdministrator())await ReviveOS.Security.AdminBroker.Run("deep-restore",[item.Action.Id]);else await optimizer.Restore(item.Action.Id);}catch(Exception ex){errors.Add(ex);}}if(errors.Count>0)throw new AggregateException(errors);log.Text="Selecionados restaurados e verificados.";}catch(Exception ex){log.Text=ex.ToString();}finally{busy=false;}};DockPanel.SetDock(buttons,Dock.Top);dock.Children.Add(buttons);DockPanel.SetDock(log,Dock.Bottom);dock.Children.Add(log);dock.Children.Add(new ScrollViewer{Content=choices,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});Content=dock;Closing+=(_,e)=>e.Cancel=busy;
  plan.Click+=async(_,_)=>{if(busy)return;busy=true;try{var inventory=await optimizer.Inventory();var recommended=DeepPlan.Recommend(inventory).Select(x=>x.Id).ToHashSet();var actions=inventory.Startup.Select(x=>DeepPlan.Describe("startup:"+x)).Concat(new[]{"SysMain","WSearch"}.Where(name=>DeepPlan.HasService(inventory,name)).Select(name=>DeepPlan.Describe("service:"+name)).Append(DeepPlan.Describe("pagefile")));items.Clear();choices.Children.Clear();foreach(var a in actions){var check=new CheckBox{Content=a.Description,IsChecked=recommended.Contains(a.Id),Margin=new Thickness(6)};items.Add((check,a));choices.Children.Add(check);choices.Children.Add(new TextBlock{Text=a.Reason+"\nRisco: "+a.Risk+(a.RequiresAdmin?"\nSolicita administrador pelo UAC quando necessário.":""),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(24,0,8,12)});}log.Text=System.Text.Json.JsonSerializer.Serialize(inventory,ReviveOS.Core.State.Json)+"\nSeleção é sugestão, não ganho comprovado. Leia os riscos. Serviços não são desativados indiscriminadamente.";}catch(Exception ex){log.Text=ex.ToString();}finally{busy=false;}};
  apply.Click+=async(_,_)=>{if(busy)return;var selected=items.Where(x=>x.Box.IsChecked==true).Select(x=>x.Action).ToArray();if(selected.Length==0)return;if(MessageBox.Show(string.Join("\n",selected.Select(x=>x.Description+": "+x.Risk))+"\nAplicar com backup e validação? Se falhar, será tentada restauração de todos os ajustes profundos pendentes.","Confirmar otimização",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;busy=true;try{if(selected.Any(x=>x.RequiresAdmin)&&!ReviveOS.Security.AdminBroker.IsAdministrator())await ReviveOS.Security.AdminBroker.Run("deep-apply",selected.Select(x=>x.Id).ToArray());else await optimizer.Apply(selected.Select(x=>x.Id));log.Text="Alterações aplicadas e verificadas. Paginação requer reboot para efeito. Meça novamente e restaure se houver regressão.";}catch(OperationCanceledException ex){log.Text=ex.Message;}catch(Exception ex){log.Text=ex.Message;try{await RestoreAll();log.Text+="\nRollback confirmado.";}catch(Exception restore){log.Text+="\nRollback incompleto: "+restore.Message+". Execute como administrador e tente restaurar novamente.";}}finally{busy=false;}};
  undo.Click+=async(_,_)=>{if(busy)return;busy=true;try{await RestoreAll();log.Text="Configurações anteriores restauradas e verificadas; paginação pode exigir reinício.";}catch(Exception ex){log.Text=ex.ToString();}finally{busy=false;}};
 }
}
